awarded-tender-amounts.sparql.template:
# Retrieve the amounts awarded per tender for a specific procedure.
# Returns: publication number, tender identifier, tenderer name, amount, currency,
# and optionally the lot and lot group identifiers.
# Change the procedure identifier below to query a different procedure.
#
# Note: The notice, procedure, and tender are linked implicitly through
# the named graph. Adding explicit links (e.g. epo:announcesRole) would
# make the query more precise but significantly slower with the OPTIONAL blocks.

PREFIX adms: <http://www.w3.org/ns/adms#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX epo: <http://data.europa.eu/a4g/ontology#>
PREFIX m8g: <http://data.europa.eu/m8g/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?procedureIdentifier ?publicationDate ?publicationNumber ?tenderIdentifier ?tendererLegalName ?offerAmountValue ?currency ?lotGroupIdentifier ?lotIdentifier

WHERE {

  # Change this to the procedure you want to look up
  VALUES (?procedureIdentifier) { ({{procedureIdentifier}}) }

  GRAPH ?g {
    # Get the procedure by its identifier
    ?procedure a epo:Procedure ;
               adms:identifier / skos:notation ?procedureIdentifier .

    # Get notice and link to procedure
    ?notice a epo:Notice ;
            epo:hasPublicationDate ?publicationDate ;
            epo:hasNoticePublicationNumber ?publicationNumber ;
            epo:refersToProcedure ?procedure .

    # Get tender details: identifier, tenderer name, and financial offer
    ?tender a epo:Tender ;
            adms:identifier / skos:notation ?tenderIdentifier ;
            epo:isSubmitedBy ?tenderer ;
            epo:hasFinancialOfferValue ?offerValue .

    ?offerValue epo:hasAmountValue ?offerAmountValue ;
                epo:hasCurrency ?currencyUri .

    ?tenderer epo:playedBy / epo:hasLegalName ?tendererLegalName .

    # Optionally get the lot the tender was submitted for
    OPTIONAL {
      ?tender epo:isSubmittedForLot ?lot .
      OPTIONAL { ?lot adms:identifier / skos:notation ?lotIdentifier . }
    }

    # Optionally get the lot group
    OPTIONAL {
      ?tender epo:isSubjectToGrouping ?lotGroup .
      ?lotGroup epo:setsGroupingContextForLot ?lot .
      OPTIONAL { ?lotGroup adms:identifier / skos:notation ?lotGroupIdentifier . }
      OPTIONAL { ?lot adms:identifier / skos:notation ?lotIdentifier . }
    }
  }

  # Resolve currency label
  ?currencyUri skos:prefLabel ?currency .
  FILTER (lang(?currency) = "en")
}
ORDER BY ?publicationNumber ?lotGroupIdentifier ?lotIdentifier

buyer-count-per-month.sparql.template:
# Retrieves the count of distinct buyers per month for a specific year.
# Returns: month (YYYY-MM) and the buyer count.
# Change the date range as per your requirements.

PREFIX epo: <http://data.europa.eu/a4g/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?month (COUNT(DISTINCT ?organisation) AS ?buyerCount)
WHERE {
  FILTER (?publicationDate >= {{publicationDateStart}} &&
          ?publicationDate <= {{publicationDateEnd}})

  GRAPH ?g {
    ?notice a epo:Notice ;
            epo:hasPublicationDate ?publicationDate ;
            epo:refersToRole ?buyer .

    ?buyer a epo:Buyer ;
           epo:playedBy ?organisation .

    BIND(SUBSTR(STR(?publicationDate), 1, 7) AS ?month)
  }
}
GROUP BY ?month
ORDER BY ?month

competition-notices.sparql.template:
# Retrieve competition notices published on a specific date, including
# procedure type, buyer name, and buyer country.
# Change the date below to query a different day.

PREFIX cccev: <http://data.europa.eu/m8g/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX epo: <http://data.europa.eu/a4g/ontology#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?publicationDate ?publicationNumber ?formType ?procedureType ?legalName ?country

WHERE {

  FILTER (?publicationDate = {{publicationDate}})
  # Filter for competition notices only
  FILTER (?formTypeUri = <http://publications.europa.eu/resource/authority/form-type/competition>)

  GRAPH ?g {
    # Get notice details and link to procedure and buyer
    ?notice a epo:Notice ;
            epo:hasPublicationDate ?publicationDate ;
            epo:hasNoticePublicationNumber ?publicationNumber ;
            epo:hasFormType ?formTypeUri ;
            epo:refersToProcedure ?procedure ;
            epo:announcesRole | epo:refersToRole ?agentInRole .

    # Get procedure type
    ?procedure epo:hasProcedureType ?procedureTypeUri .

    # Get buyer organisation and country
    { ?agentInRole a epo:Buyer ;
                   epo:playedBy ?organization .

      ?organization epo:hasLegalName ?legalName ;
                    cccev:registeredAddress / epo:hasCountryCode ?countryUri .
    }
  }

  # Resolve labels in English
  ?formTypeUri skos:prefLabel ?formType .
  FILTER (lang(?formType) = "en")

  ?procedureTypeUri skos:prefLabel ?procedureType .
  FILTER (lang(?procedureType) = "en")

  ?countryUri skos:prefLabel ?country .
  FILTER (lang(?country) = "en")
}

contracts-awarded-by-eu-inst.sparql.template:
# Retrieves contracts awarded by EU institutions and bodies.
# Returns: publication number, date, title, buyer name, procedure type, contract identifier,
#          lot identifier, framework agreement type, contract value and currency.
# Change the publication date range as per your requirements.
# Notes: 1: Here it is attempted to get the same results as that is provided in the TED site -
#          https://ted.europa.eu/en/simap/contracts-awarded-by-eu-institutions?year=2026&eu-institution=ALL
# 2: TED provides both old forms and eForms whereas this query currently fetches only eForms.
# 3: Query executes successfully with LIMIT 1000 or for a single date range 

PREFIX adms: <http://www.w3.org/ns/adms#>
PREFIX blt: <http://publications.europa.eu/resource/authority/buyer-legal-type/>
PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX epo: <http://data.europa.eu/a4g/ontology#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>

SELECT DISTINCT ?publicationNumber ?publicationDate ?title ?buyerName ?procedureType
       ?frameworkAgreementType ?contractIdentifier ?contractTitle
       ?lotIdentifier ?winner ?tenderValue ?tenderCurrency
WHERE {
  GRAPH ?g {
    # Start with buyer legal type filter (most selective)
    ?org epo:hasBuyerLegalType ?buyerLegalType ;
         epo:hasLegalName ?buyerName .

    VALUES ?buyerLegalType { blt:eu-ins-bod-ag blt:body-pl }

    ?buyer a epo:Buyer ;
           epo:playedBy ?org .

    # Notice with date filter applied early
    ?notice a epo:ResultNotice ;
            epo:hasNoticePublicationNumber ?publicationNumber ;
            epo:hasPublicationDate ?publicationDate ;
            epo:refersToProcedure ?procedure ;
            epo:refersToRole ?buyer ;
            epo:refersToLot ?lot .

    FILTER(?publicationDate >= {{publicationDateStart}} && ?publicationDate <= {{publicationDateEnd}})

    # Lot
    ?lot adms:identifier / skos:notation ?lotIdentifier .

    # Procedure
    ?procedure a epo:Procedure ;
               dcterms:title ?title ;
               epo:hasProcedureType ?procedureTypeURI .

    # Contract
    ?contract a epo:Contract ;
              adms:identifier / skos:notation ?contractIdentifier ;
              dcterms:title ?contractTitle ;
              epo:hasLotReference ?lot .

    # Framework agreement (optional)
    OPTIONAL {
      ?lot epo:isSubjectToLotSpecificTerm ?frameworkAgreementTerm .
      ?frameworkAgreementTerm a epo:FrameworkAgreementTerm ;
                              epo:hasFrameworkAgreementType ?frameworkAgreementTypeURI .
    }

    # Tender + winner + value (single optional block)
    OPTIONAL {
      ?contract epo:includesTender ?tender .
      ?tender a epo:Tender ;
              epo:isSubmittedForLot ?lot ;
              epo:isSubmitedBy ?tenderer ;
              epo:hasFinancialOfferValue ?financialOfferValue .

      ?financialOfferValue epo:hasAmountValue ?tenderValue ;
                           epo:hasCurrency ?tenderCurrencyURI .

      ?tenderer a epo:Tenderer ;
                epo:playedBy / epo:hasLegalName ?winner .
    }
  }

  # Resolve labels outside the graph (small lookups)
  ?procedureTypeURI skos:prefLabel ?procedureType .
  FILTER(LANG(?procedureType) = "en")

  OPTIONAL {
    ?frameworkAgreementTypeURI skos:prefLabel ?frameworkAgreementType .
    FILTER(LANG(?frameworkAgreementType) = "en")
  }

  OPTIONAL { ?tenderCurrencyURI dc:identifier ?tenderCurrency . }
}
#LIMIT 1000

count-of-notices-date-range.sparql.template:
# Retrieves the count (number of notices) per date range
# Returns: publication date and the count per date.
# Change the range of the publication dates as per your requirements.

PREFIX epo: <http://data.europa.eu/a4g/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?pubDate (COUNT(DISTINCT ?noticePublicationNumber) AS ?NoticeCount)
WHERE {

  FILTER (
    ?pubDate >= {{pubDateStart}} &&
    ?pubDate <= {{pubDateEnd}}
  )

  GRAPH ?g {
    ?Notice a epo:Notice ;
            epo:hasNoticePublicationNumber ?noticePublicationNumber ;
            epo:hasPublicationDate ?pubDate .
  }
}
GROUP BY ?pubDate
ORDER BY ?pubDate

highest-estimated-procedure-amount.sparq.template:
# Retrieves the notice with the highest estimated procedure amount in EUR for a specific date range.
# Returns: publication date, publication number, and the estimated procedure amount.
# Change the date range as per your requirements.

PREFIX epo: <http://data.europa.eu/a4g/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?publicationDate ?publicationNumber ?procedureEstimatedAmount
WHERE {
  FILTER (?publicationDate >= {{publicationDateStart}})
  FILTER (?publicationDate <= {{publicationDateEnd}})

  GRAPH ?g {
    ?notice a epo:Notice ;
            epo:hasPublicationDate ?publicationDate ;
            epo:hasNoticePublicationNumber ?publicationNumber ;
            epo:refersToProcedure ?procedure .

    ?procedure a epo:Procedure ;
               epo:hasEstimatedValue ?procedureEstimatedValue .

    ?procedureEstimatedValue epo:hasAmountValue ?procedureEstimatedAmount ;
                             epo:hasCurrency <http://publications.europa.eu/resource/authority/currency/EUR> .
  }
}
ORDER BY DESC(?procedureEstimatedAmount)
