joint-procurement-notice-count.sparql.template:
# Retrieves the count of notices that have more than one buyer (joint procurement) for a specific date.
# Returns: the total number of such notices.
# Change the publication date as per your requirements.

PREFIX epo: <http://data.europa.eu/a4g/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(DISTINCT ?publicationNumber) AS ?noticeCount)
WHERE {
  {
    SELECT ?publicationNumber (COUNT(DISTINCT ?legalName) AS ?buyersCount)
    WHERE {
      FILTER (?publicationDate = {{publicationDate}})

      GRAPH ?g {
        ?notice a epo:Notice ;
                epo:hasNoticePublicationNumber ?publicationNumber ;
                epo:hasPublicationDate ?publicationDate ;
                epo:refersToRole ?buyer .

        ?buyer a epo:Buyer ;
               epo:playedBy ?organization .

        ?organization epo:hasLegalName ?legalName .
      }
    }
    GROUP BY ?publicationNumber
    HAVING (COUNT(DISTINCT ?legalName) > 1)
  }
}

lots-associated-to-procedure.sparql.template:
# Retrieve the lots associated to a specific procedure.
# Returns: procedure identifier, lot identifier, lot title, and main CPV code.
# Change the procedure identifier below to query a different procedure.

PREFIX adms: <http://www.w3.org/ns/adms#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX epo: <http://data.europa.eu/a4g/ontology#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?procedureIdentifier ?lotIdentifier ?lotTitle ?lotMainCPVCode ?lotMainCPV

WHERE {

  # Change this to the procedure you want to look up
  VALUES (?procedureIdentifier) {
    ({{procedureIdentifier}})
  }

  GRAPH ?g {
    # Get procedure and its lots
    ?procedure a epo:Procedure ;
               adms:identifier / skos:notation ?procedureIdentifier ;
               epo:hasProcurementScopeDividedIntoLot ?lot .

    # Get lot details and CPV classification
    ?lot adms:identifier / skos:notation ?lotIdentifier ;
         epo:hasPurpose / epo:hasMainClassification ?lotMainCPVUri .

    OPTIONAL { ?lot dcterms:title ?lotTitle . }
  }

  # Resolve CPV code and label
  ?lotMainCPVUri dc:identifier ?lotMainCPVCode ;
                 skos:prefLabel ?lotMainCPV .
  FILTER(lang(?lotMainCPV) = "en")
}
ORDER BY ASC(?lotIdentifier)

