SELECT ?publicationDate ?noticeType (COUNT(DISTINCT ?noticePublicationNumber) AS ?NoticeCount)
WHERE {
  VALUES (?startDate ?endDate) { ({{startDate}} {{date}}) }

  FILTER (?publicationDate >= ?startDate && ?publicationDate <= ?endDate)

  GRAPH ?g {
    ?notice a epo:Notice ;
            epo:hasPublicationDate ?publicationDate ;
            epo:hasNoticePublicationNumber ?noticePublicationNumber ;
