notice-count-per-month.sparql.template:
# Retrieves the count of distinct notices per month for a specific date range.
# Returns: month (YYYY-MM) and the number of notices.
# Change the date range as per your requirements.

PREFIX epo: <http://data.europa.eu/a4g/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?month (COUNT(DISTINCT ?publicationNumber) AS ?numberOfNotices)
WHERE {
  FILTER (?publicationDate >= {{publicationDateStart}} &&
          ?publicationDate <= {{publicationDateEnd}})

  GRAPH ?g {
    ?notice a epo:Notice ;
            epo:hasPublicationDate ?publicationDate ;
            epo:hasNoticePublicationNumber ?publicationNumber .

