sme-tenders-per-date.sparql.template:
# Retrieves the total number of tenders from SMEs per publication date for a specific date range.
# Returns: publication date and the total number of tenders from SMEs.
# Change the date range as per your requirements.

PREFIX epo: <http://data.europa.eu/a4g/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?pubDate (SUM(?noOfTendersFromSMEs) AS ?totalNoOfTendersFromSMEs)
WHERE {
  FILTER (?pubDate >= {{pubDateStart}} &&
          ?pubDate <= {{pubDateEnd}})
  #FILTER (?pubNum = "00153462-2026") #uncomment for testing

  GRAPH ?g {
    ?notice a epo:Notice ;
            epo:hasNoticePublicationNumber ?pubNum ;
            epo:hasPublicationDate ?pubDate;
            epo:refersToLot ?lot.

    ?sSI a epo:SubmissionStatisticalInformation ;
         epo:summarisesInformationForAwardOutcome / epo:concernsLot ?lot; #joining notice and sSI based on lot
         epo:hasSMEReceivedTenders ?noOfTendersFromSMEs .
  }
}
GROUP BY ?pubDate
ORDER BY ?pubDate

tenderer-count-per-month.sparql.template:
# Retrieves the count of distinct tenderer organisations per month for a specific year.
# Handles both individual organisations and members of organisation groups.
# Returns: month (YYYY-MM) and the number of tenderer organisations.
# Change the date range as per your requirements.

PREFIX epo: <http://data.europa.eu/a4g/ontology#>
PREFIX org: <http://www.w3.org/ns/org#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?month (COUNT(DISTINCT ?organization) AS ?numberOfTenderers)
WHERE {
  FILTER (?publicationDate >= {{publicationDateStart}} &&
          ?publicationDate <= {{publicationDateEnd}})
  #FILTER (?publicationNumber = "00153462-2026")        

  GRAPH ?g {
    ?notice a epo:Notice ;
            epo:hasPublicationDate ?publicationDate ;
            epo:hasNoticePublicationNumber ?publicationNumber ;
            epo:announcesRole ?tenderer .

    ?tenderer a epo:Tenderer ;
              epo:playedBy ?org .
  #to ensure orgs and org group members (organizations) are considered
    { ?org a org:Organization .
      BIND(?org AS ?organization) }
    UNION
    { ?org a epo:OrganisationGroup ;
           epo:hasMember ?organization . }

    BIND(SUBSTR(STR(?publicationDate), 1, 7) AS ?month)
  }
}
GROUP BY ?month
ORDER BY ?month

top-buyer-countries-by-notice-count.spar.template:
# Retrieves the top 10 buyer countries by notice count for a specific date range.
# Returns: buyer country and the notice count, ordered by highest count.
# Change the date range as per your requirements.

PREFIX epo: <http://data.europa.eu/a4g/ontology#>
PREFIX m8g: <http://data.europa.eu/m8g/>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?buyerCountry (COUNT(DISTINCT ?publicationNumber) AS ?noticeCount)
WHERE {
  FILTER (?publicationDate >= {{publicationDateStart}} &&
          ?publicationDate <= {{publicationDateEnd}})

  GRAPH ?g {
    ?notice a epo:Notice ;
            epo:hasNoticePublicationNumber ?publicationNumber ;
            epo:hasPublicationDate ?publicationDate ;
            epo:refersToRole ?buyer .

    ?buyer a epo:Buyer ;
           epo:playedBy ?organization .

    ?organization epo:hasLegalName ?buyerName ;
                  m8g:registeredAddress ?regAdd .

    ?regAdd epo:hasCountryCode ?buyerCountryCode .
  }

  ?buyerCountryCode skos:prefLabel ?buyerCountry .
  FILTER (LANG(?buyerCountry) = "en")
}
GROUP BY ?buyerCountry
ORDER BY DESC(?noticeCount)
LIMIT 10

